"use client";

import {
	type ReactElement,
	useCallback,
	useEffect,
	useLayoutEffect,
	useRef,
	useState,
	useSyncExternalStore,
} from "react";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { type CommandPanelProps, CommandPanel } from "./command-panel";
import { commandParts } from "./command.styles";
import { SearchIcon } from "./icons";

export type CommandBlockProps = Omit<
	CommandPanelProps,
	"onClose" | "surface" | "focusOnMount" | "escapeHint" | "ref"
> & {
	/** Controlled open state; pair it with `onOpenChange`. */
	open?: boolean;
	defaultOpen?: boolean;
	onOpenChange?: (open: boolean) => void;
	/**
	 * The key that opens and closes the palette with ⌘ (Mac) or Ctrl (elsewhere). Default "k".
	 * `false` binds nothing, such as for a second palette on the page.
	 */
	shortcut?: string | false;
	/**
	 * The button that opens it. Default: a search button showing the shortcut. Pass your own element
	 * (it gets the dialog trigger's props) or `false` for none.
	 */
	trigger?: ReactElement | false;
	/** The default trigger's text. Default "Search…". */
	triggerLabel?: string;
	/** The dialog's accessible name. Default "Command palette". */
	title?: string;
};

const NONE: string[] = [];
const noop = () => () => {};
/** Apple keyboards say ⌘; the server and everything else say Ctrl until the page hydrates. */
const useApple = () =>
	useSyncExternalStore(
		noop,
		() => /Mac|iPhone|iPad|iPod/.test(navigator.userAgent),
		() => false,
	);

/** Whether a key press is ⌘ or Ctrl plus `key` and nothing else. */
export function isShortcut(
	event: Pick<KeyboardEvent, "key" | "metaKey" | "ctrlKey" | "altKey" | "shiftKey">,
	key: string,
) {
	return (
		(event.metaKey || event.ctrlKey) &&
		!event.altKey &&
		!event.shiftKey &&
		event.key.toLowerCase() === key.toLowerCase()
	);
}

/**
 * A command palette: a trigger button, ⌘K / Ctrl+K anywhere on the page, and a `CommandPanel` in a
 * native modal `<dialog>`, so the top layer, the inert page, Escape, light dismiss and focus return
 * are the browser's. Each opening starts fresh on the first page with an empty search; recent
 * commands are kept across openings.
 */
export function CommandBlock({
	open: openProp,
	defaultOpen = false,
	onOpenChange,
	shortcut = "k",
	trigger,
	triggerLabel = "Search…",
	title = "Command palette",
	recent: recentProp,
	defaultRecent = NONE,
	onRecentChange,
	...panel
}: CommandBlockProps) {
	const [inner, setInner] = useState(defaultOpen);
	const controlled = openProp !== undefined;
	const open = controlled ? openProp : inner;
	const apple = useApple();

	// A new session (a fresh panel) on every opening, however it was opened.
	const [session, setSession] = useState(0);
	const [wasOpen, setWasOpen] = useState(open);
	if (open !== wasOpen) {
		setWasOpen(open);
		if (open) setSession((n) => n + 1);
	}

	const [innerRecent, setInnerRecent] = useState(defaultRecent);
	const recent = recentProp ?? innerRecent;

	const current = useRef(open);
	useLayoutEffect(() => {
		current.current = open;
	}, [open]);

	const setOpen = useCallback(
		(next: boolean) => {
			if (next === current.current) return;
			if (!controlled) setInner(next);
			onOpenChange?.(next);
		},
		[controlled, onOpenChange],
	);

	useEffect(() => {
		if (!shortcut) return;
		const onKey = (event: KeyboardEvent) => {
			if (event.defaultPrevented || event.repeat || !isShortcut(event, shortcut)) return;
			event.preventDefault();
			setOpen(!current.current);
		};
		window.addEventListener("keydown", onKey);
		return () => window.removeEventListener("keydown", onKey);
	}, [shortcut, setOpen]);

	const keys = shortcut ? [apple ? "⌘" : "Ctrl", shortcut.toUpperCase()] : [];

	return (
		<Dialog open={open} onOpenChange={setOpen}>
			{trigger === false ? null : (
				<DialogTrigger
					asChild
					aria-keyshortcuts={
						shortcut
							? `Meta+${shortcut.toUpperCase()} Control+${shortcut.toUpperCase()}`
							: undefined
					}
				>
					{trigger ?? (
						<Button variant="outline" className={commandParts.trigger}>
							<SearchIcon />
							<span className="flex-1 text-start">{triggerLabel}</span>
							{keys.length ? (
								<span aria-hidden="true" className="flex items-center gap-1">
									{keys.map((key) => (
										<kbd key={key} className={commandParts.kbd}>
											{key}
										</kbd>
									))}
								</span>
							) : null}
						</Button>
					)}
				</DialogTrigger>
			)}
			<DialogContent showClose={false} className={commandParts.dialog}>
				<DialogTitle className="sr-only">{title}</DialogTitle>
				<CommandPanel
					key={session}
					{...panel}
					recent={recent}
					onRecentChange={(next) => {
						if (recentProp === undefined) setInnerRecent(next);
						onRecentChange?.(next);
					}}
					surface={false}
					escapeHint
					focusOnMount
					onClose={() => setOpen(false)}
				/>
			</DialogContent>
		</Dialog>
	);
}

"use client";

import {
	type CSSProperties,
	type KeyboardEvent,
	type ReactNode,
	type Ref,
	useEffect,
	useId,
	useLayoutEffect,
	useMemo,
	useRef,
	useState,
} from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
	type CommandItem,
	type CommandRow,
	commandGroups,
	commandSections,
	labels,
	pushRecent,
} from "./command-search";
import { SKELETON_ROWS, commandParts } from "./command.styles";
import {
	ArrowDownIcon,
	ArrowUpIcon,
	ChevronLeftIcon,
	ChevronRightIcon,
	ClockIcon,
	EnterIcon,
	SearchIcon,
} from "./icons";

export type CommandPanelProps = {
	/** The commands on the first page. Give one `items` to make it open a page of its own. */
	commands: CommandItem[];
	/** Runs after a command's own `onSelect`, with the page items above it. */
	onSelect?: (item: CommandItem, parents: CommandItem[]) => void;
	/** Called after a command runs, unless it has `keepOpen`. The block closes its dialog here. */
	onClose?: () => void;
	/** The accessible name of the search field and the list. Default "Commands". */
	label?: string;
	placeholder?: string;
	/** The search text (controlled). It is cleared on every page change. */
	query?: string;
	defaultQuery?: string;
	/** The new search text, and the page it is on, such as to fetch results for it. */
	onQueryChange?: (query: string, page: CommandItem | undefined) => void;
	/** `false` lists `commands` as given, for results your own search filtered. Default true. */
	filter?: boolean;
	/** Results are on their way: skeleton rows while the list is empty, a spinner while it is not. */
	loading?: boolean;
	/** What to show when nothing matches. A function gets the query. */
	empty?: ReactNode | ((query: string) => ReactNode);
	/** Recent command ids, newest first (controlled). */
	recent?: string[];
	defaultRecent?: string[];
	onRecentChange?: (recent: string[]) => void;
	/** How many recent commands to keep and list above the rest. 0 turns them off. Default 5. */
	recentLimit?: number;
	recentLabel?: string;
	/** Tabs to narrow the list to one group of the current page. */
	scopes?: boolean;
	/** The first scope tab's label. Default "All". */
	allLabel?: string;
	/** The keyboard hints along the bottom. Default true. */
	hints?: boolean;
	/** Show the Escape key in the field and the hints, for a palette in a dialog. */
	escapeHint?: boolean;
	/** Draw the raised popover surface around the panel. Default true; the dialog draws its own. */
	surface?: boolean;
	/** Focus the search field when the panel mounts. */
	focusOnMount?: boolean;
	className?: string;
	ref?: Ref<HTMLDivElement>;
};

const NONE: string[] = [];
const NO_ITEMS: CommandItem[] = [];

/** The scope tab for every group; no group name can be it. */
const ALL = "\u0000all";

/** One controlled-or-uncontrolled value, the way the other components hold theirs. */
function useControllable<T>(value: T | undefined, initial: T, onChange?: (next: T) => void) {
	const [inner, setInner] = useState(initial);
	const controlled = value !== undefined;
	const current = controlled ? value : inner;
	const set = (next: T) => {
		if (!controlled) setInner(next);
		onChange?.(next);
	};
	return [current, set] as const;
}

/** The label with its matched letters in `<mark>`, one per run. */
function Highlighted({ text, match }: { text: string; match: number[] }) {
	if (!match.length) return text;
	const marked = new Set(match);
	const parts: ReactNode[] = [];
	let start = 0;
	for (let i = 1; i <= text.length; i++) {
		if (i < text.length && marked.has(i) === marked.has(start)) continue;
		const piece = text.slice(start, i);
		parts.push(
			marked.has(start) ? (
				<mark key={start} className={commandParts.match}>
					{piece}
				</mark>
			) : (
				piece
			),
		);
		start = i;
	}
	return parts;
}

function Keys({ keys }: { keys: ReactNode[] }) {
	return (
		<span className="flex shrink-0 items-center gap-1">
			{keys.map((key, i) => (
				// oxlint-disable-next-line react/no-array-index-key -- keys can repeat, such as ⇧ ⇧
				<kbd key={i} className={commandParts.kbd}>
					{key}
				</kbd>
			))}
		</span>
	);
}

/**
 * A searchable list of commands: a combobox field over a listbox (`aria-activedescendant`), fuzzy
 * filtering, groups, recent commands, nested pages, loading and empty states, and keyboard hints.
 * Use it inline, or let `CommandBlock` put it in a dialog behind ⌘K.
 */
export function CommandPanel({
	commands,
	onSelect,
	onClose,
	label = "Commands",
	placeholder = "Type a command or search…",
	query: queryProp,
	defaultQuery = "",
	onQueryChange,
	filter = true,
	loading = false,
	empty,
	recent: recentProp,
	defaultRecent = NONE,
	onRecentChange,
	recentLimit = 5,
	recentLabel = "Recent",
	scopes = false,
	allLabel = "All",
	hints = true,
	escapeHint = false,
	surface = true,
	focusOnMount = false,
	className,
	ref,
}: CommandPanelProps) {
	const base = useId();
	const listId = `${base}-list`;
	const hintId = `${base}-hint`;
	const inputRef = useRef<HTMLInputElement>(null);
	const viewportRef = useRef<HTMLDivElement>(null);
	const measureRef = useRef<HTMLDivElement>(null);
	// Only the arrow keys scroll the active row into view; the pointer is already on it.
	const scrollOnMove = useRef(false);

	const [pages, setPages] = useState<CommandItem[]>([]);
	const page = pages.at(-1);
	const [query, setQueryValue] = useControllable(queryProp, defaultQuery);
	const [recent, setRecent] = useControllable(recentProp, defaultRecent, onRecentChange);
	const [scope, setScope] = useState("");
	const [activeKey, setActiveKey] = useState<string | null>(null);
	const [loaded, setLoaded] = useState<Record<string, CommandItem[]>>({});
	const [errors, setErrors] = useState<Record<string, string>>({});

	const setQuery = (next: string, on: CommandItem | undefined = page) => {
		setQueryValue(next);
		setActiveKey(null);
		onQueryChange?.(next, on);
	};

	const pageItems = useMemo(
		() =>
			!page ? commands : Array.isArray(page.items) ? page.items : (loaded[page.id] ?? NO_ITEMS),
		[page, commands, loaded],
	);
	const error = page ? errors[page.id] : undefined;
	const pageLoading = !!page && typeof page.items === "function" && !(page.id in loaded) && !error;
	const busy = loading || pageLoading;

	const groups = useMemo(() => (scopes ? commandGroups(pageItems) : []), [scopes, pageItems]);
	const activeScope = groups.includes(scope) ? scope : "";

	const sections = useMemo(
		() =>
			commandSections({
				items: pageItems,
				query,
				root: !page,
				recent: recentLimit > 0 ? recent : [],
				recentLabel,
				scope: activeScope || undefined,
				filter,
			}),
		[pageItems, query, page, recentLimit, recent, recentLabel, activeScope, filter],
	);
	const rows = useMemo(() => sections.flatMap((section) => section.rows), [sections]);
	const enabled = rows.filter((row) => !row.item.disabled);
	const active = enabled.find((row) => row.key === activeKey) ?? enabled[0];
	const optionId = (row: CommandRow) => `${base}-o${rows.indexOf(row)}`;
	const hasIcons = rows.some((row) => row.item.icon || row.key.startsWith("recent:"));

	useEffect(() => {
		if (focusOnMount) inputRef.current?.focus();
	}, [focusOnMount]);

	// The viewport eases its height to the content's: script measures, CSS animates `--_h`.
	useLayoutEffect(() => {
		const viewport = viewportRef.current;
		const content = measureRef.current;
		if (!viewport || !content || typeof ResizeObserver === "undefined") return;
		const observer = new ResizeObserver(() => {
			const height = content.offsetHeight;
			// A closed dialog measures 0; keep the last height so reopening does not grow from 0.
			if (height > 0) viewport.style.setProperty("--_h", `${height}px`);
		});
		observer.observe(content);
		return () => observer.disconnect();
	}, []);

	useLayoutEffect(() => {
		if (!scrollOnMove.current || !active) return;
		scrollOnMove.current = false;
		if (active === enabled[0]) viewportRef.current?.scrollTo({ top: 0 });
		else document.getElementById(optionId(active))?.scrollIntoView({ block: "nearest" });
	});

	const load = (item: CommandItem) => {
		if (typeof item.items !== "function") return;
		setErrors((all) => {
			const next = { ...all };
			delete next[item.id];
			return next;
		});
		item.items().then(
			(list) => setLoaded((all) => ({ ...all, [item.id]: list })),
			(reason: unknown) =>
				setErrors((all) => ({
					...all,
					[item.id]: reason instanceof Error ? reason.message : "These commands did not load.",
				})),
		);
	};

	const goTo = (next: CommandItem[]) => {
		setPages(next);
		setScope("");
		setQuery("", next.at(-1));
		viewportRef.current?.scrollTo({ top: 0 });
		inputRef.current?.focus();
	};

	const run = (row: CommandRow) => {
		const { item, parents } = row;
		if (item.disabled) return;
		if (item.items) {
			goTo([...pages, ...parents, item]);
			if (typeof item.items === "function" && !(item.id in loaded)) load(item);
			return;
		}
		item.onSelect?.(item);
		onSelect?.(item, [...pages, ...parents]);
		if (recentLimit > 0) setRecent(pushRecent(recent, item.id, recentLimit));
		if (!item.keepOpen) onClose?.();
	};

	const move = (to: CommandRow | undefined) => {
		if (!to) return;
		scrollOnMove.current = true;
		setActiveKey(to.key);
	};

	const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
		if (event.nativeEvent.isComposing) return;
		const at = active ? enabled.indexOf(active) : -1;
		const count = enabled.length;
		let handled = true;
		if (event.key === "ArrowDown") move(enabled[(at + 1) % count]);
		else if (event.key === "ArrowUp") move(enabled[(at - 1 + count) % count]);
		else if (event.key === "Home") move(enabled[0]);
		else if (event.key === "End") move(enabled[count - 1]);
		else if (event.key === "Enter") {
			if (active) run(active);
		} else if ((event.key === "Backspace" || event.key === "Escape") && pages.length && !query) {
			// On a page, Escape steps back instead of closing (a handled keydown is no close request).
			goTo(pages.slice(0, -1));
		} else handled = false;
		if (handled) event.preventDefault();
	};

	const announcement = busy
		? "Loading…"
		: error
			? error
			: query
				? rows.length
					? `${rows.length} ${rows.length === 1 ? "result" : "results"}`
					: "No results"
				: page
					? `${page.label}, ${rows.length} ${rows.length === 1 ? "command" : "commands"}`
					: "";

	const emptyContent = error ? (
		<>
			<p className="m-0">{error}</p>
			<Button variant="secondary" size="sm" onClick={() => page && load(page)}>
				Try again
			</Button>
		</>
	) : typeof empty === "function" ? (
		empty(query)
	) : (
		(empty ?? <p className="m-0">{query ? `No results for “${query}”.` : "No commands here."}</p>)
	);

	return (
		<div
			ref={ref}
			data-slot="command"
			className={cn(commandParts.root, surface && `rx-surface ${commandParts.surface}`, className)}
		>
			{pages.length ? (
				<nav aria-label="Pages" className={commandParts.crumbs}>
					<Button
						variant="ghost"
						size="sm"
						onClick={() => goTo(pages.slice(0, -1))}
						aria-label={`Back to ${pages.at(-2)?.label ?? label}`}
					>
						<ChevronLeftIcon />
						Back
					</Button>
					<ol className="m-0 flex min-w-0 list-none items-center gap-1 p-0">
						{pages.map((item, i) => (
							<li key={item.id} className="flex min-w-0 items-center gap-1">
								{i > 0 ? <ChevronRightIcon className="size-3 shrink-0 opacity-60" /> : null}
								<Badge
									tone={i === pages.length - 1 ? "accent" : "neutral"}
									aria-current={i === pages.length - 1 ? "page" : undefined}
									className="truncate"
								>
									{item.label}
								</Badge>
							</li>
						))}
					</ol>
				</nav>
			) : null}

			<div className={commandParts.search}>
				<Input
					ref={inputRef}
					size="lg"
					variant="filled"
					leadingIcon={<SearchIcon />}
					trailingIcon={
						busy && rows.length ? (
							<span className={commandParts.spinner} />
						) : escapeHint ? (
							<kbd className={commandParts.kbd}>esc</kbd>
						) : undefined
					}
					role="combobox"
					aria-label={page ? `${label}: ${page.label}` : label}
					aria-expanded="true"
					aria-controls={listId}
					aria-activedescendant={active ? optionId(active) : undefined}
					aria-autocomplete="list"
					aria-describedby={hintId}
					aria-busy={busy || undefined}
					autoComplete="off"
					autoCorrect="off"
					spellCheck={false}
					enterKeyHint="go"
					placeholder={page?.placeholder ?? placeholder}
					value={query}
					onChange={(event) => setQuery(event.target.value)}
					onKeyDown={onKeyDown}
				/>
				<span id={hintId} hidden>
					Up and down arrows move through the results, Enter chooses one
					{pages.length ? ", Backspace in an empty field goes back" : ""}.
				</span>
			</div>

			{groups.length > 1 ? (
				<Tabs
					value={activeScope || ALL}
					onValueChange={(value) => {
						setScope(value === ALL ? "" : value);
						setActiveKey(null);
					}}
					className={commandParts.scopes}
				>
					<TabsList variant="underline" size="sm" aria-label="Scope">
						<TabsTrigger value={ALL}>{allLabel}</TabsTrigger>
						{groups.map((name) => (
							<TabsTrigger key={name} value={name}>
								{name}
							</TabsTrigger>
						))}
					</TabsList>
				</Tabs>
			) : null}

			<div ref={viewportRef} className={commandParts.viewport}>
				<div ref={measureRef}>
					<div
						role="listbox"
						id={listId}
						aria-label={label}
						aria-busy={busy || undefined}
						className={commandParts.list}
					>
						{sections.map((section, s) => {
							const headingId = `${base}-g${s}`;
							return (
								<div
									key={section.key}
									role={section.heading ? "group" : "presentation"}
									aria-labelledby={section.heading ? headingId : undefined}
									className={commandParts.group}
								>
									{section.heading ? (
										<div id={headingId} aria-hidden="true" className={commandParts.heading}>
											{section.heading}
										</div>
									) : null}
									{section.rows.map((row) => {
										const { item } = row;
										const isActive = row === active;
										const trail = labels(row.parents).join(" › ");
										const description = [trail, item.description].filter(Boolean).join(" · ");
										return (
											// Keyboard users stay in the field (aria-activedescendant); a click runs it.
											// oxlint-disable-next-line jsx-a11y/click-events-have-key-events
											<div
												key={row.key}
												id={optionId(row)}
												role="option"
												tabIndex={-1}
												aria-selected={isActive}
												aria-disabled={item.disabled || undefined}
												data-active={isActive ? "" : undefined}
												data-page={item.items ? "" : undefined}
												className={commandParts.item}
												onPointerMove={() => {
													if (!item.disabled && !isActive) setActiveKey(row.key);
												}}
												onMouseDown={(event) => event.preventDefault()}
												onClick={() => run(row)}
											>
												{hasIcons ? (
													<span className={commandParts.itemIcon} aria-hidden="true">
														{item.icon ?? (row.key.startsWith("recent:") ? <ClockIcon /> : null)}
													</span>
												) : null}
												<span className={commandParts.itemText}>
													<span className={commandParts.itemLabel}>
														<Highlighted text={item.label} match={row.match} />
													</span>
													{description ? (
														<span className={commandParts.itemDescription}>{description}</span>
													) : null}
												</span>
												{item.badge ? <Badge tone={item.badgeTone}>{item.badge}</Badge> : null}
												{item.shortcut?.length ? (
													<span aria-hidden="true">
														<Keys keys={item.shortcut} />
													</span>
												) : null}
												{item.items ? (
													<ChevronRightIcon className={commandParts.itemChevron} />
												) : null}
											</div>
										);
									})}
								</div>
							);
						})}
						<span className={commandParts.highlight} aria-hidden="true" />
					</div>
					{busy && !rows.length ? (
						<div aria-hidden="true">
							{Array.from({ length: SKELETON_ROWS }, (_, i) => (
								<div
									key={i}
									className={commandParts.skeleton}
									style={{ "--_i": i } as CSSProperties}
								>
									<span />
									<span />
								</div>
							))}
						</div>
					) : null}
					{!busy && !rows.length ? <div className={commandParts.empty}>{emptyContent}</div> : null}
				</div>
			</div>

			{hints ? (
				<div className={commandParts.footer} aria-hidden="true">
					<span>
						<Keys keys={[<ArrowUpIcon key="up" />, <ArrowDownIcon key="down" />]} />
						Navigate
					</span>
					<span>
						<Keys keys={[<EnterIcon key="enter" />]} />
						{active?.item.items ? "Open" : "Select"}
					</span>
					{pages.length ? (
						<span>
							<Keys keys={["⌫"]} />
							Back
						</span>
					) : escapeHint ? (
						<span>
							<Keys keys={["esc"]} />
							Close
						</span>
					) : null}
				</div>
			) : null}

			<p className="sr-only" aria-live="polite" aria-atomic="true">
				{announcement}
			</p>
		</div>
	);
}

import type { ReactNode } from "react";
import type { BadgeTone } from "@/components/ui/badge.styles";

/** One command. Give it `onSelect` to run it, or `items` to open a page of more commands. */
export type CommandItem = {
	/** Unique among the commands; also the key for recent items. */
	id: string;
	label: string;
	/** The heading it is listed under. Items without one are listed under no heading. */
	group?: string;
	/** A second line, muted. Searched too. */
	description?: string;
	/** Extra words that find it, such as synonyms. Not shown. */
	keywords?: string[];
	/** A decorative 16px icon, such as a HugeIcons element. */
	icon?: ReactNode;
	/** Keys to show at the end, such as `["⌘", "N"]`. Only a hint: the block does not bind them. */
	shortcut?: string[];
	/** A short label in a Badge, such as "New". */
	badge?: string;
	badgeTone?: BadgeTone;
	disabled?: boolean;
	/** A page of commands, or a function that loads them (the list shows a loading state). */
	items?: CommandItem[] | (() => Promise<CommandItem[]>);
	/** The search placeholder on this item's page. */
	placeholder?: string;
	/** Runs when the command is chosen with Enter or a click. */
	onSelect?: (item: CommandItem) => void;
	/** Keep the palette open after it runs, such as a toggle. */
	keepOpen?: boolean;
};

/** A row in the list: the item, the page items above it, and the label's matched letters. */
export type CommandRow = {
	key: string;
	item: CommandItem;
	/** The pages the item sits in below the current one, when a search on the first page finds it. */
	parents: CommandItem[];
	match: number[];
};

export type CommandSection = { key: string; heading?: string; rows: CommandRow[] };

const BOUNDARY = /[\s\-_/.:()[\]]/;

/** Lowercase without accents, one character per character so match positions still line up. */
function fold(text: string) {
	const folded = text.normalize("NFKD").replace(/\p{M}/gu, "").toLowerCase();
	return folded.length === text.length ? folded : text.toLowerCase();
}

const atBoundary = (text: string, i: number) => i === 0 || BOUNDARY.test(text[i - 1]);

/** The query's letters in order, each at its earliest place after the last (always finds one). */
function earliest(text: string, query: string) {
	const indices: number[] = [];
	let from = 0;
	for (const char of query) {
		const i = text.indexOf(char, from);
		if (i < 0) return null;
		indices.push(i);
		from = i + 1;
	}
	return indices;
}

/** Like `earliest`, but a letter that starts a word wins over one inside a word ("gs" → Git Status). */
function preferWords(text: string, query: string) {
	const indices: number[] = [];
	let from = 0;
	let prev = -2;
	for (const char of query) {
		let first = -1;
		let word = -1;
		for (let i = from; i < text.length; i++) {
			if (text[i] !== char) continue;
			if (first < 0) first = i;
			if (atBoundary(text, i)) {
				word = i;
				break;
			}
		}
		if (first < 0) return null;
		const i = first === prev + 1 || word < 0 ? first : word;
		indices.push(i);
		prev = i;
		from = i + 1;
	}
	return indices;
}

/**
 * How well `query` matches `text`, and which letters of `text` matched, or `null`. A run of the
 * query's letters (best at the start, or at a word's start) beats letters spread over the text; a
 * spread match counts only when most of its letters start a word or follow the previous one, so
 * "nf" finds "New file" but two random letters do not find everything.
 */
export function fuzzyMatch(
	text: string,
	query: string,
): { score: number; indices: number[] } | null {
	const t = fold(text);
	const q = fold(query).replace(/\s+/g, " ").trim();
	if (!q) return { score: 0, indices: [] };

	const at = t.indexOf(q);
	if (at >= 0) {
		const score =
			1000 +
			(t.length === q.length ? 1000 : 0) +
			(at === 0 ? 400 : 0) +
			(atBoundary(t, at) ? 200 : 0) -
			at;
		return { score, indices: Array.from({ length: q.length }, (_, k) => at + k) };
	}

	const letters = q.replace(/ /g, "");
	if (letters.length < 2) return null;
	const indices = preferWords(t, letters) ?? earliest(t, letters);
	if (!indices) return null;
	let score = 0;
	let good = 0;
	indices.forEach((i, k) => {
		const run = k > 0 && i === indices[k - 1] + 1;
		const word = atBoundary(t, i);
		if (run || word) good++;
		score += run ? 30 : word ? 24 : 2;
	});
	if (good / indices.length < 0.6) return null;
	return { score: score - (indices.at(-1)! - indices[0]), indices };
}

/** Score an item against a query: the label counts most, then keywords, description, group, path. */
export function scoreItem(item: CommandItem, query: string, path: string[] = []) {
	const whole = fuzzyMatch(item.label, query);
	if (whole && whole.indices.length && whole.score >= 1000) return whole;

	const tokens = query.trim().split(/\s+/).filter(Boolean);
	if (!tokens.length) return { score: 0, indices: [] };
	const others = [...(item.keywords ?? []), item.description ?? "", item.group ?? "", ...path];
	const indices = new Set<number>();
	let score = 0;
	for (const token of tokens) {
		const label = fuzzyMatch(item.label, token);
		const other = Math.max(-1, ...others.map((text) => fuzzyMatch(text, token)?.score ?? -1));
		if (!label && other < 0) return whole;
		if (label && label.score >= other / 2) {
			score += label.score;
			for (const i of label.indices) indices.add(i);
		} else score += other / 2;
	}
	const best = { score, indices: [...indices].toSorted((a, b) => a - b) };
	return whole && whole.score > best.score ? whole : best;
}

/** The labels of a row's parents, for its breadcrumb. */
export const labels = (parents: CommandItem[]) => parents.map((parent) => parent.label);

type Entry = { item: CommandItem; parents: CommandItem[] };

/** Every item in `items` and, below it, in the pages that are already arrays (not loaders). */
export function flatten(items: CommandItem[], parents: CommandItem[] = []): Entry[] {
	return items.flatMap((item) => [
		{ item, parents },
		...(Array.isArray(item.items) ? flatten(item.items, [...parents, item]) : []),
	]);
}

export type SectionOptions = {
	items: CommandItem[];
	query: string;
	/** On the first page, a query also searches the pages below it. */
	root: boolean;
	/** Recent ids, newest first; listed first while the query is empty on the first page. */
	recent?: string[];
	recentLabel?: string;
	/** Only this group (a scope), or every group. */
	scope?: string;
	/** `false` lists the items as given, for results filtered by your own search. */
	filter?: boolean;
};

/** Group rows under their headings, in the order the headings first appear. */
function group(rows: CommandRow[], heading: (row: CommandRow) => string | undefined) {
	const sections = new Map<string, CommandSection>();
	for (const row of rows) {
		const name = heading(row);
		const key = `group:${name ?? ""}`;
		const section = sections.get(key) ?? { key, heading: name, rows: [] };
		section.rows.push(row);
		sections.set(key, section);
	}
	return [...sections.values()];
}

const row = (prefix: string, { item, parents }: Entry, match: number[] = []): CommandRow => ({
	key: `${prefix}:${item.id}`,
	item,
	parents,
	match,
});

/** The sections to list for a page, a query, the recent ids and a scope. */
export function commandSections({
	items,
	query,
	root,
	recent = [],
	recentLabel = "Recent",
	scope,
	filter = true,
}: SectionOptions): CommandSection[] {
	const inScope = (item: CommandItem) => !scope || item.group === scope;

	if (!query.trim() || !filter) {
		const sections = group(
			items.filter(inScope).map((item) => row("item", { item, parents: [] })),
			(r) => r.item.group,
		);
		if (!root || scope || !recent.length || query.trim()) return sections;
		const known = new Map(flatten(items).map((entry) => [entry.item.id, entry]));
		const rows = recent.flatMap((id) => {
			const entry = known.get(id);
			return entry && !entry.item.items ? [row("recent", entry)] : [];
		});
		return rows.length ? [{ key: "recent", heading: recentLabel, rows }, ...sections] : sections;
	}

	const entries = root ? flatten(items) : items.map((item) => ({ item, parents: [] }));
	const scored = entries
		.filter(({ item }) => inScope(item))
		.flatMap((entry) => {
			const match = scoreItem(entry.item, query, labels(entry.parents));
			return match ? [{ entry, match }] : [];
		})
		// Shallower first on a tie, so a page's own item beats the same words deeper down.
		.toSorted(
			(a, b) => b.match.score - a.match.score || a.entry.parents.length - b.entry.parents.length,
		);
	return group(
		scored.map(({ entry, match }) => row("item", entry, match.indices)),
		(r) => r.item.group ?? r.parents.at(-1)?.label,
	);
}

/** The groups on a page, in order, for scope tabs. */
export function commandGroups(items: CommandItem[]) {
	return [...new Set(items.flatMap((item) => (item.group ? [item.group] : [])))];
}

/** Put `id` first in a recent list, without repeats, capped at `limit`. */
export function pushRecent(recent: string[], id: string, limit: number) {
	return [id, ...recent.filter((other) => other !== id)].slice(0, Math.max(0, limit));
}

/**
 * Class names for the command block. Its look and motion live in `command-block.css` (your global
 * CSS, when installed from the registry); the field, badges, buttons and tabs are the components'.
 */
export const commandParts = {
	/** The panel: field, scopes, list and footer in a column. */
	root: "rx-command",
	/** Added to the root when it stands alone (not in the dialog): the raised popover surface. */
	surface: "rx-command-surface",
	/** The Dialog panel holding a palette: narrower, higher up, no padding of its own. */
	dialog: "rx-command-dialog",
	/** The search field's row. */
	search: "rx-command-search",
	/** The pages above the current one, with a back button. */
	crumbs: "rx-command-crumbs",
	/** The scope tabs' row. */
	scopes: "rx-command-scopes",
	/** Scrolls the list and eases its height to the content's (`--_h`, measured in script). */
	viewport: "rx-command-viewport",
	/** The `listbox`. Scopes the highlight's anchor, so two palettes never share one. */
	list: "rx-command-list",
	/** A `group` of options under a heading. */
	group: "rx-command-group",
	heading: "rx-command-heading",
	/** One `option`. `data-active` on the one the arrow keys are on: it becomes the anchor. */
	item: "rx-command-item",
	itemIcon: "rx-command-item-icon",
	itemText: "rx-command-item-text",
	itemLabel: "rx-command-item-label",
	itemDescription: "rx-command-item-description",
	/** The arrow on an option that opens a page. */
	itemChevron: "rx-command-item-chevron",
	/** The matched letters in a label. */
	match: "rx-command-match",
	/** The list's last child: the highlight that slides to the anchored option. */
	highlight: "rx-command-highlight",
	/** A key cap, such as ⌘ or K. */
	kbd: "rx-command-kbd",
	/** Turns in the field while more results load. */
	spinner: "rx-command-spinner",
	/** Placeholder rows while commands load. */
	skeleton: "rx-command-skeleton",
	/** The message when nothing matches, or a page failed to load. */
	empty: "rx-command-empty",
	/** The keyboard hints along the bottom. */
	footer: "rx-command-footer",
	/** The trigger button's key caps. */
	trigger: "rx-command-trigger",
} as const;

